120	
121	/* Stat cards */
122	.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin-bottom: 24px; }
123	.stat { background: var(--bg2); border: 1px solid var(--bd); border-radius: var(--radius); padding: 14px 16px; }
124	.stat-label { font-size: 11px; color: var(--tx3); text-transform: uppercase; letter-spacing: 0.04em; font-weight: 500; }
125	.stat-value { font-size: 22px; font-weight: 600; margin-top: 4px; }
126	
127	/* Copy selector */
128	.copy-select { padding: 6px 10px; border: 1px solid var(--bd); border-radius: 6px; font-size: 12px; font-family: var(--sans); background: var(--bg); color: var(--tx); outline: none; }
129	
130	.hidden { display: none !important; }
131	</style>
132	</head>
133	<body>
134	
135	<div class="sidebar">
136	  <div class="sidebar-header">
137	    <div class="sidebar-logo"><span>C</span> Polyglot</div>
138	    <div class="sidebar-sub">Agent management dashboard</div>
139	  </div>
140	  <div class="sidebar-nav" id="nav"></div>
141	  <div class="sidebar-footer" id="footer">Loading...</div>
142	</div>
143	
144	<div class="main">
145	  <div class="main-header">
146	    <div class="main-title" id="page-title">Dashboard</div>
147	    <div class="main-subtitle" id="page-subtitle">Overview of all agents and projects</div>
148	  </div>
149	  <div class="main-content" id="content"></div>
150	</div>
151	
152	<div class="toast" id="toast"></div>
153	
154	<script>
155	// --- State ---
156	let state = {
157	  config: null,
158	  projects: [],
159	  globalAgents: [],
160	  globalClaudeMd: '',
161	  currentPage: 'dashboard',
162	  currentProject: null,
163	};
164	
165	// --- API ---
166	const api = {
167	  get: (url) => fetch(url).then(r => r.json()),
168	  put: (url, body) => fetch(url, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }).then(r => r.json()),
169	  post: (url, body) => fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }).then(r => r.json()),
170	  del: (url) => fetch(url, { method: 'DELETE' }).then(r => r.json()),
171	};
172	
173	// --- Toast ---
174	function toast(msg) {
175	  const el = document.getElementById('toast');
176	  el.textContent = msg;
177	  el.classList.add('show');
178	  setTimeout(() => el.classList.remove('show'), 2500);
179	}
180	
181	// --- Load Data ---
182	async function loadAll() {
183	  state.config = await api.get('/api/config');
184	  if (!state.config.projectDirs || state.config.projectDirs.length === 0) {
185	    renderSetup();
186	    return;
187	  }
188	  state.projects = await api.get('/api/projects');
189	  state.globalAgents = await api.get('/api/global/agents');
190	  const gmd = await api.get('/api/global/claude-md');
191	  state.globalClaudeMd = gmd.content;
192	  renderNav();
193	  renderPage();
194	}
195	
196	// --- Setup ---
197	function renderSetup() {
198	  const dirs = state.config?.projectDirs || [];
199	  document.getElementById('nav').innerHTML = '';
200	  document.getElementById('footer').textContent = 'Setup required';
201	  setPageHeader('Welcome', 'Add your project directories to get started');
202	  document.getElementById('content').innerHTML = `
203	    <div class="setup-wrap">
204	      <div class="setup-title">Welcome to Polyglot</div>
205	      <div class="setup-desc">Add the folders where your projects live. Polyglot will scan them and find all projects with Claude Code agents.</div>
206	      <div style="display:flex;gap:8px;margin-bottom:12px">
207	        <input class="editor-input" id="dir-input" placeholder="~/projects" style="flex:1" />
208	        <button class="btn btn-primary" onclick="addDir()">Add</button>
209	      </div>
210	      <div class="dir-list" id="dir-list">
211	        ${dirs.map((d, i) => `<div class="dir-item">${d}<span class="remove" onclick="removeDir(${i})">×</span></div>`).join('')}
212	      </div>
213	      ${dirs.length > 0 ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="finishSetup()">Start scanning</button>` : ''}
214	    </div>
215	  `;
216	}
217	
218	async function addDir() {
219	  const input = document.getElementById('dir-input');
220	  const dir = input.value.trim();
221	  if (!dir) return;
222	  const dirs = state.config?.projectDirs || [];
223	  dirs.push(dir);
224	  await api.post('/api/config/project-dirs', { dirs });
225	  state.config.projectDirs = dirs;
226	  input.value = '';
227	  renderSetup();
228	}
229	
230	async function removeDir(i) {
231	  const dirs = state.config.projectDirs;
232	  dirs.splice(i, 1);
233	  await api.post('/api/config/project-dirs', { dirs });
234	  renderSetup();
235	}
236	
237	async function finishSetup() {
238	  await loadAll();
239	}
240	
241	// --- Navigation ---
242	function renderNav() {
243	  const nav = document.getElementById('nav');
244	  const totalAgents = state.globalAgents.length + state.projects.reduce((s, p) => s + p.agentCount, 0);
245	  let html = `
246	    <div class="nav-section">Overview</div>
247	    <div class="nav-item ${state.currentPage === 'dashboard' ? 'active' : ''}" onclick="goTo('dashboard')">
248	      <span class="nav-icon">◉</span>Dashboard<span class="badge">${totalAgents}</span>
249	    </div>
250	    <div class="nav-section">Global</div>
251	    <div class="nav-item ${state.currentPage === 'global-agents' ? 'active' : ''}" onclick="goTo('global-agents')">
252	      <span class="nav-icon">⚡</span>Global agents<span class="badge">${state.globalAgents.length}</span>
253	    </div>
254	    <div class="nav-item ${state.currentPage === 'global-claude-md' ? 'active' : ''}" onclick="goTo('global-claude-md')">
255	      <span class="nav-icon">📄</span>Global CLAUDE.md
256	    </div>
257	    <div class="nav-section">Projects (${state.projects.length})</div>
258	  `;
259	  for (const p of state.projects) {
260	    const active = state.currentPage === 'project' && state.currentProject?.id === p.id;
261	    html += `<div class="nav-item ${active ? 'active' : ''}" onclick="goToProject('${p.id}')">
262	      <span class="nav-icon">◆</span>${p.name}<span class="badge">${p.agentCount}</span>
263	    </div>`;
264	  }
265	  html += `
266	    <div class="nav-section" style="margin-top:16px"></div>
267	    <div class="nav-item" onclick="goTo('settings')">
268	      <span class="nav-icon">⚙</span>Settings
269	    </div>
270	  `;
271	  nav.innerHTML = html;
272	  document.getElementById('footer').textContent = `${state.projects.length} projects · ${totalAgents} agents`;
273	}
274	
275	// --- Page Router ---
276	function setPageHeader(title, subtitle) {
277	  document.getElementById('page-title').textContent = title;
278	  document.getElementById('page-subtitle').textContent = subtitle || '';
279	}
280	
281	function goTo(page) {
282	  state.currentPage = page;
283	  state.currentProject = null;
284	  renderNav();
285	  renderPage();
286	}
287	
288	function goToProject(id) {
289	  state.currentPage = 'project';
290	  state.currentProject = state.projects.find(p => p.id === id);
291	  renderNav();
292	  renderPage();
293	}
294	
295	function renderPage() {
296	  const c = document.getElementById('content');
297	  switch (state.currentPage) {
298	    case 'dashboard': return renderDashboard(c);
299	    case 'global-agents': return renderGlobalAgents(c);
300	    case 'global-claude-md': return renderGlobalClaudeMd(c);
301	    case 'project': return renderProject(c);
302	    case 'settings': return renderSettings(c);
303	  }
304	}
305	
306	// --- Dashboard ---
307	function renderDashboard(c) {
308	  setPageHeader('Dashboard', 'Overview of all agents and projects');
309	  const totalAgents = state.globalAgents.length + state.projects.reduce((s, p) => s + p.agentCount, 0);
310	  const totalCommands = state.projects.reduce((s, p) => s + p.commands.length, 0);
311	  const hasGlobalMd = state.globalClaudeMd ? 'Yes' : 'Not set';
