file.content:
/* Stat cards */
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin-bottom: 24px; }
.stat { background: var(--bg2); border: 1px solid var(--bd); border-radius: var(--radius); padding: 14px 16px; }
.stat-label { font-size: 11px; color: var(--tx3); text-transform: uppercase; letter-spacing: 0.04em; font-weight: 500; }
.stat-value { font-size: 22px; font-weight: 600; margin-top: 4px; }

/* Copy selector */
.copy-select { padding: 6px 10px; border: 1px solid var(--bd); border-radius: 6px; font-size: 12px; font-family: var(--sans); background: var(--bg); color: var(--tx); outline: none; }

.hidden { display: none !important; }
</style>
</head>
<body>

<div class="sidebar">
  <div class="sidebar-header">
    <div class="sidebar-logo"><span>C</span> Polyglot</div>
    <div class="sidebar-sub">Agent management dashboard</div>
  </div>
  <div class="sidebar-nav" id="nav"></div>
  <div class="sidebar-footer" id="footer">Loading...</div>
</div>

<div class="main">
  <div class="main-header">
    <div class="main-title" id="page-title">Dashboard</div>
    <div class="main-subtitle" id="page-subtitle">Overview of all agents and projects</div>
  </div>
  <div class="main-content" id="content"></div>
</div>

<div class="toast" id="toast"></div>

<script>
// --- State ---
let state = {
  config: null,
  projects: [],
  globalAgents: [],
  globalClaudeMd: '',
  currentPage: 'dashboard',
  currentProject: null,
};

// --- API ---
const api = {
  get: (url) => fetch(url).then(r => r.json()),
  put: (url, body) => fetch(url, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }).then(r => r.json()),
  post: (url, body) => fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }).then(r => r.json()),
  del: (url) => fetch(url, { method: 'DELETE' }).then(r => r.json()),
};

// --- Toast ---
function toast(msg) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.classList.add('show');
  setTimeout(() => el.classList.remove('show'), 2500);
}

// --- Load Data ---
async function loadAll() {
  state.config = await api.get('/api/config');
  if (!state.config.projectDirs || state.config.projectDirs.length === 0) {
    renderSetup();
    return;
  }
  state.projects = await api.get('/api/projects');
  state.globalAgents = await api.get('/api/global/agents');
  const gmd = await api.get('/api/global/claude-md');
  state.globalClaudeMd = gmd.content;
  renderNav();
  renderPage();
}

// --- Setup ---
function renderSetup() {
  const dirs = state.config?.projectDirs || [];
  document.getElementById('nav').innerHTML = '';
  document.getElementById('footer').textContent = 'Setup required';
  setPageHeader('Welcome', 'Add your project directories to get started');
  document.getElementById('content').innerHTML = `
    <div class="setup-wrap">
      <div class="setup-title">Welcome to Polyglot</div>
      <div class="setup-desc">Add the folders where your projects live. Polyglot will scan them and find all projects with Claude Code agents.</div>
      <div style="display:flex;gap:8px;margin-bottom:12px">
        <input class="editor-input" id="dir-input" placeholder="~/projects" style="flex:1" />
        <button class="btn btn-primary" onclick="addDir()">Add</button>
      </div>
      <div class="dir-list" id="dir-list">
        ${dirs.map((d, i) => `<div class="dir-item">${d}<span class="remove" onclick="removeDir(${i})">×</span></div>`).join('')}
      </div>
      ${dirs.length > 0 ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="finishSetup()">Start scanning</button>` : ''}
    </div>
  `;
}

async function addDir() {
  const input = document.getElementById('dir-input');
  const dir = input.value.trim();
  if (!dir) return;
  const dirs = state.config?.projectDirs || [];
  dirs.push(dir);
  await api.post('/api/config/project-dirs', { dirs });
  state.config.projectDirs = dirs;
  input.value = '';
  renderSetup();
}

async function removeDir(i) {
  const dirs = state.config.projectDirs;
  dirs.splice(i, 1);
  await api.post('/api/config/project-dirs', { dirs });
  renderSetup();
}

async function finishSetup() {
  await loadAll();
}

// --- Navigation ---
function renderNav() {
  const nav = document.getElementById('nav');
  const totalAgents = state.globalAgents.length + state.projects.reduce((s, p) => s + p.agentCount, 0);
  let html = `
    <div class="nav-section">Overview</div>
    <div class="nav-item ${state.currentPage === 'dashboard' ? 'active' : ''}" onclick="goTo('dashboard')">
      <span class="nav-icon">◉</span>Dashboard<span class="badge">${totalAgents}</span>
    </div>
    <div class="nav-section">Global</div>
    <div class="nav-item ${state.currentPage === 'global-agents' ? 'active' : ''}" onclick="goTo('global-agents')">
      <span class="nav-icon">⚡</span>Global agents<span class="badge">${state.globalAgents.length}</span>
    </div>
    <div class="nav-item ${state.currentPage === 'global-claude-md' ? 'active' : ''}" onclick="goTo('global-claude-md')">
      <span class="nav-icon">📄</span>Global CLAUDE.md
    </div>
    <div class="nav-section">Projects (${state.projects.length})</div>
  `;
  for (const p of state.projects) {
    const active = state.currentPage === 'project' && state.currentProject?.id === p.id;
    html += `<div class="nav-item ${active ? 'active' : ''}" onclick="goToProject('${p.id}')">
      <span class="nav-icon">◆</span>${p.name}<span class="badge">${p.agentCount}</span>
    </div>`;
  }
  html += `
    <div class="nav-section" style="margin-top:16px"></div>
    <div class="nav-item" onclick="goTo('settings')">
      <span class="nav-icon">⚙</span>Settings
    </div>
  `;
  nav.innerHTML = html;
  document.getElementById('footer').textContent = `${state.projects.length} projects · ${totalAgents} agents`;
}

// --- Page Router ---
function setPageHeader(title, subtitle) {
  document.getElementById('page-title').textContent = title;
  document.getElementById('page-subtitle').textContent = subtitle || '';
}

function goTo(page) {
  state.currentPage = page;
  state.currentProject = null;
  renderNav();
  renderPage();
}

function goToProject(id) {
  state.currentPage = 'project';
  state.currentProject = state.projects.find(p => p.id === id);
  renderNav();
  renderPage();
}

function renderPage() {
  const c = document.getElementById('content');
  switch (state.currentPage) {
    case 'dashboard': return renderDashboard(c);
    case 'global-agents': return renderGlobalAgents(c);
    case 'global-claude-md': return renderGlobalClaudeMd(c);
    case 'project': return renderProject(c);
    case 'settings': return renderSettings(c);
  }
}

// --- Dashboard ---
function renderDashboard(c) {
  setPageHeader('Dashboard', 'Overview of all agents and projects');
  const totalAgents = state.globalAgents.length + state.projects.reduce((s, p) => s + p.agentCount, 0);
  const totalCommands = state.projects.reduce((s, p) => s + p.commands.length, 0);
  const hasGlobalMd = state.globalClaudeMd ? 'Yes' : 'Not set';
  c.innerHTML = `
    <div class="stats">
      <div class="stat"><div class="stat-label">Total agents</div><div class="stat-value">${totalAgents}</div></div>
      <div class="stat"><div class="stat-label">Global agents</div><div class="stat-value">${state.globalAgents.length}</div></div>
      <div class="stat"><div class="stat-label">Projects</div><div class="stat-value">${state.projects.length}</div></div>
      <div class="stat"><div class="stat-label">Commands</div><div class="stat-value">${totalCommands}</div></div>
    </div>
    <div style="margin-bottom:20px">

