    ${dom.length||wt.length?`<div class="oc-tags">${dom.map(t=>`<span class="ot domain" onclick="event.stopPropagation();orgToggleTag('domain','${t}')">${t}</span>`).join('')}${wt.map(t=>`<span class="ot wt" onclick="event.stopPropagation();orgToggleTag('work-type','${t}')">${t}</span>`).join('')}</div>`:''}
    <div class="oc-foot">
      <span style="display:flex;align-items:center;gap:5px"><span class="odot" style="background:${dc}"></span></span>
      ${a.reportsTo?`<span>→ ${a.reportsTo}</span>`:''}
    </div>
  </div>`;
}

function orgRenderContent() {
  const el = document.getElementById('orgContent');
  if (!el) return;
  const agents = orgFiltered();
  if (state.orgView === 'grid') {
    el.innerHTML = agents.length
      ? `<div class="agent-grid">${agents.map(orgCard).join('')}</div>`
      : '<div class="empty"><div class="empty-icon">🔍</div><div class="empty-title">No agents match</div></div>';
  } else if (state.orgView === 'list') {
    orgRenderList(el, agents);
  } else if (state.orgView === 'dept') {
    orgRenderByDept(el, agents);
  } else {
    orgRenderByTech(el, agents);
  }
}

function orgRenderList(el, agents) {
  if (!agents.length) { el.innerHTML = '<div class="empty"><div class="empty-icon">🔍</div><div class="empty-title">No agents match</div></div>'; return; }
  const sc = state.orgSortCol, sd = state.orgSortDir;
  const srt = [...agents].sort((a,b)=>{ let va=a[sc]||a.id, vb=b[sc]||b.id; return va<vb?-sd:va>vb?sd:0; });
  const th = (c,l) => `<th onclick="orgSort('${c}')">${l}${sc===c?(sd>0?' ↑':' ↓'):''}</th>`;
  el.innerHTML = `<div style="overflow-x:auto"><table class="org-lv"><thead><tr>${th('name','Agent')}${th('title','Role')}${th('department','Dept')}${th('levelTitle','Level')}<th>Tech tags</th><th>Domain tags</th></tr></thead><tbody>${srt.map(a=>{
    const dc=ORG_DEPT_COLORS[a.department]||'#9ca3af';
    return`<tr onclick="orgOpenPanel('${a.id}')">
      <td style="font-weight:600"><span class="odot" style="background:${dc};margin-right:6px"></span>${escHtml(a.name||a.id)}</td>
      <td style="color:var(--tx2)">${escHtml(a.title||'')}</td>
      <td style="color:var(--tx2)">${a.department||''}</td>
      <td>${a.levelTitle?`<span class="obadge ob-lv">${a.levelTitle}</span>`:''}</td>
      <td><div class="oc-tags">${(a.tags?.tech||[]).slice(0,4).map(t=>`<span class="ot tech">${t}</span>`).join('')}</div></td>
      <td><div class="oc-tags">${(a.tags?.domain||[]).slice(0,3).map(t=>`<span class="ot domain">${t}</span>`).join('')}</div></td>
    </tr>`;
  }).join('')}</tbody></table></div>`;
}

function orgRenderByDept(el, agents) {
  let html = '';
  for (const did of ORG_DEPT_ORDER) {
    const members = agents.filter(a => a.department === did);
    if (!members.length) continue;
    const dc = ORG_DEPT_COLORS[did]||'#9ca3af', dl = (state.orgDepts[did]?.label)||did;
    html += `<div class="org-sg"><div class="org-sg-head"><span class="org-sg-dot" style="background:${dc}"></span><span class="org-sg-ttl">${dl}</span><span class="org-sg-cnt">${members.length} agents</span></div><div class="agent-grid">${members.map(orgCard).join('')}</div></div>`;
  }
  el.innerHTML = html || '<div class="empty"><div class="empty-icon">🔍</div><div class="empty-title">No agents match</div></div>';
}

function orgRenderByTech(el, agents) {
  let html = '';
  for (const tv of ORG_TAXONOMY.tech.tags) {
    const members = agents.filter(a => (a.tags?.tech||[]).includes(tv));
    if (!members.length) continue;
    html += `<div class="org-sg"><div class="org-sg-head"><span class="org-sg-dot" style="background:var(--accent)"></span><span class="org-sg-ttl">${tv}</span><span class="org-sg-cnt">${members.length} agents</span><span class="org-sg-filter" onclick="orgToggleTag('tech','${tv}')">+ filter</span></div><div class="agent-grid">${members.map(orgCard).join('')}</div></div>`;
  }
  const noTech = agents.filter(a => !(a.tags?.tech||[]).length);
  if (noTech.length) html += `<div class="org-sg"><div class="org-sg-head"><span class="org-sg-dot" style="background:var(--tx3)"></span><span class="org-sg-ttl">No tech tag</span><span class="org-sg-cnt">${noTech.length}</span></div><div class="agent-grid">${noTech.map(orgCard).join('')}</div></div>`;
  el.innerHTML = html || '<div class="empty"><div class="empty-icon">🔍</div><div class="empty-title">No agents match</div></div>';
}

function orgToggleTag(cat, val) {
  const arr = state.orgFilters[cat];
  const idx = arr.indexOf(val);
  if (idx >= 0) arr.splice(idx, 1); else arr.push(val);
  orgRenderToolbar(); orgRenderContent();
}

function orgClearFilters() {
  state.orgFilters = { tech: [], domain: [], 'work-type': [], q: '' };
  orgRenderToolbar(); orgRenderContent();
}

let _orgSt;
function orgSearch(v) {
  clearTimeout(_orgSt);
  _orgSt = setTimeout(() => { state.orgFilters.q = v.trim(); orgRenderToolbar(); orgRenderContent(); }, 120);
}

function orgSetView(v) {
  state.orgView = v;
  orgRenderToolbar(); orgRenderContent();
}

function orgSort(col) {
  if (state.orgSortCol === col) state.orgSortDir *= -1; else { state.orgSortCol = col; state.orgSortDir = 1; }
  orgRenderList(document.getElementById('orgContent'), orgFiltered());
}

function orgOpenPanel(id) {
  const a = state.orgAgents.find(x => x.id === id);
  if (!a) return;
  const ov = document.getElementById('orgPanelOv');
  if (!ov) return;
  const tg = a.tags || {};
  const allTech = tg.tech||[], allDom = tg.domain||[], allWt = tg['work-type']||[];
  const samePod  = a.pod ? state.orgAgents.filter(x => x.pod===a.pod && x.id!==a.id) : [];
  const sameTech = allTech.length ? state.orgAgents.filter(x => x.id!==a.id && (x.tags?.tech||[]).some(t=>allTech.includes(t))) : [];
  const topSkills = Object.entries(a.skills||{}).sort((a,b)=>b[1].score-a[1].score).slice(0,6);
  const mc = a.model==='opus'?'ob-opus':a.model==='haiku'?'ob-haiku':'ob-sonnet';

  document.getElementById('orgPanelName').textContent  = a.name||a.id;
  document.getElementById('orgPanelTitle').textContent = `${a.title||''} · ${a.department||''}`;

  let body = `<div class="op-sec">
    <div class="op-meta"><span class="op-ml">Model</span><span class="obadge ${mc}">${a.model||'sonnet'}</span></div>
    <div class="op-meta"><span class="op-ml">Level</span>${a.levelTitle||'—'}</div>
    <div class="op-meta"><span class="op-ml">Status</span>${a.status||'active'}</div>
    ${a.reportsTo?`<div class="op-meta"><span class="op-ml">Reports to</span>${a.reportsTo}</div>`:''}
    ${a.secondaryReportsTo?`<div class="op-meta"><span class="op-ml">Also reports</span>${a.secondaryReportsTo}</div>`:''}
    ${a.pod?`<div class="op-meta"><span class="op-ml">Pod</span>${a.pod}</div>`:''}
    ${a.hiredAt?`<div class="op-meta"><span class="op-ml">Hired</span>${a.hiredAt.slice(0,10)}</div>`:''}
  </div>`;

  if (a.description) body += `<div class="op-sec"><div class="op-sec-title">Description</div><div class="op-desc">${escHtml(a.description)}</div></div>`;

  if (allTech.length||allDom.length||allWt.length) body += `<div class="op-sec">
    <div class="op-sec-title">Tags</div>
    ${allTech.length?`<div class="op-tag-row">${allTech.map(t=>`<span class="ot tech">${t}</span>`).join('')}</div>`:''}
    ${allDom.length?`<div class="op-tag-row">${allDom.map(t=>`<span class="ot domain">${t}</span>`).join('')}</div>`:''}
    ${allWt.length?`<div class="op-tag-row">${allWt.map(t=>`<span class="ot wt">${t}</span>`).join('')}</div>`:''}
  </div>`;

  if (topSkills.length) body += `<div class="op-sec"><div class="op-sec-title">Top Skills</div>${topSkills.map(([sk,d])=>`<div class="sk-row"><span class="sk-lbl">${sk}</span><div class="sk-bg"><div class="sk-fill" style="width:${Math.round(d.score*100)}%"></div></div><span class="sk-pct">${Math.round(d.score*100)}%</span></div>`).join('')}</div>`;

  if (samePod.length) body += `<div class="op-sec"><div class="op-sec-title">Same Pod · ${a.pod}</div><div class="op-rel">${samePod.map(x=>`<span class="op-rc" onclick="orgOpenPanel('${x.id}')">${x.name||x.id}</span>`).join('')}</div></div>`;

  if (sameTech.length) {
    const show = sameTech.slice(0,12);
    body += `<div class="op-sec"><div class="op-sec-title">Same Tech Stack · ${sameTech.length}</div><div class="op-rel">${show.map(x=>`<span class="op-rc" onclick="orgOpenPanel('${x.id}')">${x.name||x.id}</span>`).join('')}${sameTech.length>12?`<span style="font-size:11px;color:var(--tx3);padding:3px 6px">+${sameTech.length-12} more</span>`:''}</div></div>`;
  }

  document.getElementById('orgPanelBody').innerHTML = body;
  ov.classList.add('open');
}

function orgClosePanel() { document.getElementById('orgPanelOv')?.classList.remove('open'); }

// --- Modal ---

