toolUseResult.originalFile:
#!/usr/bin/env bash
# find-agents.sh — Query the Polyglot agent registry from the terminal
# Usage: ./find-agents.sh --tech shopify
#        ./find-agents.sh --tech figma --work-type design
#        ./find-agents.sh --domain ecommerce --work-type testing
#        ./find-agents.sh --department engineering
#        ./find-agents.sh --tier leadership
#        ./find-agents.sh --q "bug fix"
#        ./find-agents.sh --list-tags
#        ./find-agents.sh --tech shopify --json

REGISTRY="$HOME/.claude/org/registry.json"
TAXONOMY="$HOME/.claude/org/tag-taxonomy.json"

if [[ ! -f "$REGISTRY" ]]; then
  echo "Error: registry.json not found at $REGISTRY" >&2
  exit 1
fi

TECH="" DOMAIN="" WORKTYPE="" DEPT="" TIER="" STATUS="" QUERY="" JSON_OUT=0 LIST_TAGS=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    --tech) TECH="$2"; shift 2;;
    --domain) DOMAIN="$2"; shift 2;;
    --work-type) WORKTYPE="$2"; shift 2;;
    --department) DEPT="$2"; shift 2;;
    --tier) TIER="$2"; shift 2;;
    --status) STATUS="$2"; shift 2;;
    --q) QUERY="$2"; shift 2;;
    --json) JSON_OUT=1; shift;;
    --list-tags) LIST_TAGS=1; shift;;
    -h|--help)
      echo "Usage: find-agents.sh [options]"
      echo ""
      echo "Options:"
      echo "  --tech <tag[,tag]>        Filter by tech tag (OR within, e.g. shopify,figma)"
      echo "  --domain <tag[,tag]>      Filter by domain tag"
      echo "  --work-type <tag[,tag]>   Filter by work-type tag"
      echo "  --department <id>         Filter by department"
      echo "  --tier <tier>             Filter by tier (engineer|leadership|creative|analyst)"
      echo "  --status <status>         Filter by status (active|probation|pip|retired)"
      echo "  --q <query>               Search name, title, id"
      echo "  --json                    Output raw JSON"
      echo "  --list-tags               List all available tags"
      echo ""
      echo "Filter logic: AND across categories, OR within each category"
      echo ""
      echo "Examples:"
      echo "  ./find-agents.sh --tech shopify"
      echo "  ./find-agents.sh --tech figma --work-type design"
      echo "  ./find-agents.sh --domain ecommerce --work-type testing"
      echo "  ./find-agents.sh --department engineering"
      exit 0;;
    *) echo "Unknown option: $1" >&2; exit 1;;
  esac
done

node - "$REGISTRY" "$TAXONOMY" "$TECH" "$DOMAIN" "$WORKTYPE" "$DEPT" "$TIER" "$STATUS" "$QUERY" "$JSON_OUT" "$LIST_TAGS" <<'EOF'
const fs = require('fs');
const [,, REGISTRY, TAXONOMY, techArg, domArg, wtArg, deptArg, tierArg, statusArg, queryArg, jsonOut, listTags] = process.argv;

const registry = JSON.parse(fs.readFileSync(REGISTRY, 'utf-8'));
const agents = Object.values(registry.agents || {});

if (listTags === '1') {
  try {
    const tax = JSON.parse(fs.readFileSync(TAXONOMY, 'utf-8'));
    for (const [cat, data] of Object.entries(tax.categories || {})) {
      console.log(`\n\x1b[1m${data.label} (${cat})\x1b[0m`);
      for (const [tag, info] of Object.entries(data.tags || {})) {
        console.log(`  ${tag.padEnd(18)} ${info.description}`);
      }
    }
  } catch {
    console.log('tag-taxonomy.json not found');
  }
  process.exit(0);
}

const splitArg = s => s ? s.split(',').map(v => v.trim()).filter(Boolean) : [];
const techFilter = splitArg(techArg);
const domFilter = splitArg(domArg);
const wtFilter = splitArg(wtArg);

const results = agents.filter(a => {
  const tg = a.tags || {};
  if (techFilter.length && !techFilter.some(v => (tg.tech || []).includes(v))) return false;
  if (domFilter.length && !domFilter.some(v => (tg.domain || []).includes(v))) return false;
  if (wtFilter.length && !wtFilter.some(v => (tg['work-type'] || []).includes(v))) return false;
  if (deptArg && a.department !== deptArg) return false;
  if (tierArg && a.tier !== tierArg) return false;
  if (statusArg && a.status !== statusArg) return false;
  if (queryArg) {
    const q = queryArg.toLowerCase();
    if (!a.id.includes(q) && !(a.title || '').toLowerCase().includes(q)) return false;
  }
  return true;
});

if (jsonOut === '1') {
  console.log(JSON.stringify(results, null, 2));
  process.exit(0);
}

if (!results.length) {
  console.log('No agents match the given filters.');
  process.exit(0);
}

// Print table
const cols = [
  { key: 'id', label: 'AGENT', width: 18 },
  { key: 'title', label: 'ROLE', width: 26 },
  { key: 'department', label: 'DEPT', width: 14 },
  { key: 'levelTitle', label: 'LEVEL', width: 12 },
  { key: 'tech', label: 'TECH TAGS', width: 36 },
];

const pad = (s, n) => String(s || '').slice(0, n).padEnd(n);
const sep = cols.map(c => '─'.repeat(c.width)).join('──');

console.log('');
console.log(cols.map(c => '\x1b[1m' + pad(c.label, c.width) + '\x1b[0m').join('  '));
console.log(sep);

for (const a of results.sort((a, b) => (a.department || '').localeCompare(b.department || '') || a.id.localeCompare(b.id))) {
  const techTags = (a.tags?.tech || []).join(', ');
  console.log([
    pad(a.id, cols[0].width),
    pad(a.title, cols[1].width),
    pad(a.department, cols[2].width),
    pad(a.levelTitle, cols[3].width),
    pad(techTags, cols[4].width),
  ].join('  '));
}

console.log('');
console.log(`${results.length} agent${results.length !== 1 ? 's' : ''} found`);
EOF

